insert into public.island_planning_documents
(municipality_id,document_type,title,status,document_date,effective_date,source_id,source_url,document_url,summary,checked_at)
values
('santa-cruz','pdm','Plano Diretor Municipal de Santa Cruz — plano aprovado em 2004','in_force','2004-04-29','2004-06-05','santa-cruz-municipality','https://www.cm-santacruz.pt/','https://www.cm-santacruz.pt/index.php/files/589/Revisao-PDM/2681/Relatorio-de-Fundamentacao-da-Revisao-do-PDM-de-Santa-Cruz---Junho-2019.pdf','The municipality records the original PDM was approved in 2004 and entered into force after publication in June 2004. The plan has been subject to multiple corrections and partial suspensions; this record is not a consolidated legal text. Always check current amendments and area-specific restrictions.',now()),
('santa-cruz','pdm','Suspensão parcial do PDM de Santa Cruz — Santo da Serra (Resolução n.º 1304/2023)','not_checked','2023-12-11','2023-12-12','santa-cruz-municipality','https://www.cm-santacruz.pt/','https://www.cm-santacruz.pt/index.php/files/26/Plano-Director-Municipal/3444/Suspensao-Parcial-do-PDM-na-freguesia-do-Santo-da-Serra.pdf?preview=1','Regional resolution ratified a partial suspension of the Santa Cruz PDM for the Santo da Serra area and adopted preventive measures. The published suspension was for two years, extendable by one year. Its current validity/extension after December 2025 has not been verified; do not rely on this record as current without checking the latest municipal and JORAM acts.',now()),
('santa-cruz','pdm','Suspensão parcial do PDM de Santa Cruz — Cancela, Caniço (Resolução n.º 747/2024)','not_checked','2024-09-19','2024-09-20','santa-cruz-municipality','https://www.cm-santacruz.pt/','https://www.cm-santacruz.pt/index.php/files/26/Plano-Director-Municipal/4264/Suspensao-Parcial-do-PDM-na-zona-da-Cancela.pdf?preview=1','Regional resolution ratified a partial suspension of the PDM in the Cancela / Sítio da Quinta area of Caniço and adopted preventive measures. Verify any extension or replacement plan after the initial validity period before relying on this restriction for a current parcel decision.',now()),
('santana','pdm','Revisão do Plano Diretor Municipal de Santana — Resolução n.º 401/2017','in_force','2017-06-05','2017-07-05','santana-municipality','https://www.cm-santana.com/areas-de-atuacao/servicos-municipais/urbanismo','https://www.cm-santana.com/areas-de-atuacao/transparencia-e-consulta/todos-os-documentos','The municipality states the first revision was published in JORAM on 4 July 2017 and entered into force on 5 July 2017. The 2004 PDM is marked revoked in the document register. Check later amendments and the municipality''s ongoing revision procedure.',now()),
('santana','pdm','Alteração da 1.ª Revisão do PDM de Santana — procedimento iniciado em fevereiro de 2025','under_revision','2025-02-17',null,'santana-municipality','https://www.cm-santana.com/viver-e-investir/participacao-e-cidadania/noticias/detalhe/3810-aberto-o-procedimento-de-alteracao-da-1-revisao-do-plano-diretor-municipal','https://www.cm-santana.com/viver-e-investir/participacao-e-cidadania/noticias/detalhe/3810-aberto-o-procedimento-de-alteracao-da-1-revisao-do-plano-diretor-municipal','The municipality opened a public-participation procedure for an amendment to the first PDM revision from 17 February to 7 March 2025. The municipal urbanism page, updated in October 2026, says a new PDM is being finalised. No final approval/publication was verified in this check.',now())
on conflict do nothing;

update public.island_sources
set update_note='Official Santa Cruz municipal source for the 2004 PDM and partial-suspension resolutions. Two area-specific suspensions were published in 2023 and 2024; their initial validity periods may have elapsed, and any extensions/replacement plans must be checked before a parcel-level assessment.',
last_checked_at=now(),is_active=true
where id='santa-cruz-municipality';
update public.island_sources
set update_note='Official Santana urbanism portal and document register. The 2017 PDM revision is in force; the 2004 PDM is marked revoked. The municipality opened a further amendment procedure in February 2025 and states in October 2026 that a new PDM is being finalised.',
last_checked_at=now(),is_active=true
where id='santana-municipality';
